import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const y=JSON.parse('{"title":"Phase 2 · Everyday Content Work","description":"Expand from one narrow task family to email, calendar, documents, tables, and the web.","frontmatter":{"title":"Phase 2 · Everyday Content Work","description":"Expand from one narrow task family to email, calendar, documents, tables, and the web.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-2.md","filePath":"en/delivery/stage-2.md","lastUpdated":1793859143000}'),n={name:"en/delivery/stage-2.md"};function d(s,e,l,i,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="phase-2-·-everyday-content-work" tabindex="-1">Phase 2 · Everyday Content Work <a class="header-anchor" href="#phase-2-·-everyday-content-work" aria-label="Permalink to &quot;Phase 2 · Everyday Content Work&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 2 expands Hearth from one narrow task family to most everyday content work: reading email, calendars, files, and knowledge bases; handling documents, tables, and web material; drafting content; and sending or writing after approval. The order must be read-only first, drafting second, and external writes last.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-2/2-1.html">2.1 Connect read-only information sources</a></td><td>Show what the system read and where it came from.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-2/2-2.html">2.2 Process documents, tables, and web material</a></td><td>Produce results with sources that can be checked and reused.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-2/2-3.html">2.3 Draft, approve, and write externally</a></td><td>Draft first, approve second, and execute an external write only once.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-2/2-4.html">2.4 Accept everyday content work</a></td><td>Prove less time, better accuracy, and recoverability with real daily tasks.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Connect read-only sources first so the user can see what was read.</li><li>Add document, table, and web material processing with citations.</li><li>Then complete drafting, approval, and sending or writing under a test account.</li><li>Finally accept with real daily tasks for time saved, accuracy, and failure recovery.</li></ol>',7)])])}const p=t(n,[["render",d]]);export{y as __pageData,p as default};
